}

export function CodeBlock({ files, defaultTab = 0 }: { files: CodeFile[]; defaultTab?: number }) {
  const [activeTab, setActiveTab] = useState(defaultTab);
  const [copied, setCopied] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const file = files[activeTab];
  const lines = file.code.split("\n");

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(file.code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      // Clipboard API unavailable ; no-op
    }
  };

  return (
    <div className="w-full max-w-lg overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_25px_60px_-25px_rgba(0,0,0,0.15)] dark:border-white/10 dark:bg-neutral-950 dark:shadow-[0_25px_60px_-25px_rgba(0,0,0,0.6)]">
      <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 pl-1 pr-2 dark:border-white/10 dark:bg-white/[0.02]">
        <div role="tablist" aria-label="Files" className="flex items-center gap-0.5 overflow-x-auto py-1.5 pl-1 scrollbar-hide">
          {files.map((f, i) => (
            <button
              key={f.name}
              type="button"
              role="tab"
              aria-selected={activeTab === i}
              onClick={() => setActiveTab(i)}
              className={`shrink-0 rounded-md px-2.5 py-1 font-mono text-xs transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-500 ${
                activeTab === i
                  ? "bg-slate-200 text-slate-900 dark:bg-white/10 dark:text-slate-100"
                  : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
              }`}
            >
              {f.name}
            </button>
          ))}
        </div>
        <div className="flex shrink-0 items-center gap-2 pl-2">
          <span className="hidden text-[11px] text-slate-500 sm:inline">{file.lang}</span>
          <button
            type="button"
            onClick={handleCopy}
            aria-label={copied ? "Code copied" : "Copy code"}
            title={copied ? "Code copied" : "Copy code"}
            className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-200 dark:focus-visible:outline-emerald-500"
          >
            {copied ? <CheckIcon /> : <CopyIcon />}
          </button>
        </div>
      </div>

      <AnimatePresence mode="wait" initial={false}>
        <motion.div
          key={activeTab}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.15 }}
          className="overflow-x-auto px-4 py-4"
        >
          <table className="border-collapse font-mono text-[13px] leading-relaxed">
            <tbody>
              {lines.map((line, i) => (
                <motion.tr
                  key={i}
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, x: -6 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.2, delay: i * 0.02, ease: [0.16, 1, 0.3, 1] }}
                >
                  <td className="select-none pr-4 text-right text-slate-300 dark:text-white/25">{i + 1}</td>
                  <td className="whitespace-pre">
                    {line.length === 0
                      ? " "
                      : tokenizeLine(line).map((t, ti) => (
                          <span key={ti} className={t.cls}>
                            {t.text}
                          </span>
                        ))}
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

