export function TestResults({
  suite,
  tests,
  autoPlay = true,
}: {
  suite: string;
  tests: TestCase[];
  autoPlay?: boolean;
}) {
  const [playId, setPlayId] = useState(0);
  return <TestResultsRun key={playId} suite={suite} tests={tests} autoPlay={autoPlay} onReplay={() => setPlayId((id) => id + 1)} />;
}

function TestResultsRun({
  suite,
  tests,
  autoPlay,
  onReplay,
}: {
  suite: string;
  tests: TestCase[];
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const [statuses, setStatuses] = useState<TestStatus[]>(() => (autoPlay ? tests.map(() => "pending") : tests.map((t) => t.outcome)));
  const [finished, setFinished] = useState(!autoPlay);
  const [expanded, setExpanded] = useState<number | null>(null);
  const [elapsedMs, setElapsedMs] = useState(0);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!autoPlay) return;
    startRef.current = performance.now();
    let cumulative = 0;
    let cancelled = false;
    const timeouts: ReturnType<typeof setTimeout>[] = [];

    tests.forEach((test, i) => {
      const d = shouldReduceMotion ? 30 : test.duration;
      const startAt = cumulative;
      const endAt = cumulative + d;
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          setStatuses((s) => s.map((v, idx) => (idx === i ? "running" : v)));
        }, startAt)
      );
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          setStatuses((s) => s.map((v, idx) => (idx === i ? test.outcome : v)));
        }, endAt)
      );
      cumulative = endAt;
    });
    timeouts.push(
      setTimeout(() => {
        if (!cancelled) setFinished(true);
      }, cumulative + 150)
    );

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, shouldReduceMotion]);

  useEffect(() => {
    if (finished) return;
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [finished]);

  const passed = statuses.filter((s) => s === "pass").length;
  const failed = statuses.filter((s) => s === "fail").length;
  const total = tests.length;
  const passedPct = (passed / total) * 100;
  const failedPct = (failed / total) * 100;

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="mb-1 flex items-center gap-2">
        <p className="truncate font-mono text-xs font-medium text-slate-500 dark:text-slate-400">{suite}</p>
        <span className="ml-auto shrink-0 text-xs tabular-nums text-slate-400 dark:text-slate-500">
          {finished ? `Ran in ${formatElapsed(elapsedMs)}` : formatElapsed(elapsedMs)}
        </span>
        {finished && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Re-run tests"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div className="mb-3 flex items-center gap-2">
        <div className="flex h-1.5 flex-1 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10">
          <motion.span className="h-full bg-emerald-500" animate={{ width: `${passedPct}%` }} transition={{ duration: 0.25 }} />
          <motion.span className="h-full bg-rose-500" animate={{ width: `${failedPct}%` }} transition={{ duration: 0.25 }} />
        </div>
        <p className="shrink-0 text-xs text-slate-400 dark:text-slate-500">
          <span className="font-medium text-emerald-600 dark:text-emerald-400">{passed} passed</span>
          {failed > 0 && (
            <>
              {" · "}
              <span className="font-medium text-rose-600 dark:text-rose-400">{failed} failed</span>
            </>
          )}
        </p>
      </div>

      <ul className="flex flex-col" role="list">
        {tests.map((test, i) => {
          const status = statuses[i];
          const resolved = status === "pass" || status === "fail";
          const canExpand = status === "fail";
          const isExpanded = expanded === i;
          return (
            <li key={test.name} className="border-t border-slate-100 first:border-t-0 dark:border-white/5">
              <button
                type="button"
                disabled={!canExpand}
                onClick={() => setExpanded((e) => (e === i ? null : i))}
                className="flex w-full items-center gap-2.5 py-2 text-left disabled:cursor-default"
              >
                <StatusIcon status={status} shouldReduceMotion={shouldReduceMotion} />
                <span className={`min-w-0 flex-1 truncate text-sm ${resolved ? "text-slate-700 dark:text-slate-200" : "text-slate-400 dark:text-slate-600"}`}>
                  {test.name}
                </span>
                {canExpand && (
                  <motion.span
                    animate={{ rotate: isExpanded ? 90 : 0 }}
                    transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
                    className="shrink-0 text-slate-400"
                  >
                    <ChevronIcon />
                  </motion.span>
                )}
              </button>
              <AnimatePresence initial={false}>
                {canExpand && isExpanded && (
                  <motion.div
                    initial={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                    animate={shouldReduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
                    exit={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
                    transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.4, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.28, ease: [0.22, 1, 0.36, 1] } }}
                    className="overflow-hidden"
                  >
                    <motion.p
                      initial={shouldReduceMotion ? undefined : { y: -8 }}
                      animate={{ y: 0 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.32, ease: [0.22, 1, 0.36, 1], delay: 0.06 }}
                      className="mb-2 ml-6 rounded-lg border border-rose-500/20 bg-rose-500/5 px-3 py-2 font-mono text-xs leading-relaxed text-rose-700 dark:text-rose-400"
                    >
                      {test.message}
                    </motion.p>
                  </motion.div>
                )}
              </AnimatePresence>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, steps, useReducedMotion } from "framer-motion";

interface OutputLine {
  text: string;
  tone?: "success";
}

interface Command {
  cmd: string;
  output: OutputLine[];
}

const CHAR_MS = 18;
const LINE_MS = 260;
const POST_TYPE_PAUSE = 220;
const POST_OUTPUT_PAUSE = 180;

interface Snapshot {
  cmdIndex: number;
  typedLen: number;
  outputRevealed: number;
  phase: "typing" | "output";
}

interface ScheduleStep {
  delay: number;
  snapshot: Snapshot;
}

function buildSchedule(commands: Command[]): ScheduleStep[] {
  const steps: ScheduleStep[] = [];
  let t = 0;
  commands.forEach((c, ci) => {
    for (let i = 1; i <= c.cmd.length; i++) {
      t += CHAR_MS;
      steps.push({ delay: t, snapshot: { cmdIndex: ci, typedLen: i, outputRevealed: 0, phase: "typing" } });
    }
    t += POST_TYPE_PAUSE;
    c.output.forEach((_, oi) => {
      t += LINE_MS;
      steps.push({ delay: t, snapshot: { cmdIndex: ci, typedLen: c.cmd.length, outputRevealed: oi + 1, phase: "output" } });
    });
    t += POST_OUTPUT_PAUSE;
  });
  return steps;
}

function TerminalIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <rect x="2" y="4" width="20" height="16" rx="2" />
      <path d="m6 9 3 3-3 3" />
      <path d="M12 15h6" />
    </svg>
  );
}

function ReplayIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 12a9 9 0 1 0 2.6-6.3" />
      <path d="M3 4v5h5" />
    </svg>
  );
}

function Cursor({ shouldReduceMotion }: { shouldReduceMotion: boolean | null }) {
  return (
    <motion.span
      aria-hidden
      className="ml-0.5 inline-block h-3.5 w-[7px] translate-y-0.5 bg-emerald-600 dark:bg-emerald-500"
      animate={shouldReduceMotion ? undefined : { opacity: [1, 0, 1] }}
      transition={{ duration: 1, repeat: Infinity, ease: steps(2) }}
    />
  );
}

export function Terminal({ commands, autoPlay = true }: { commands: Command[]; autoPlay?: boolean }) {
  const [playId, setPlayId] = useState(0);
  return <TerminalRun key={playId} commands={commands} autoPlay={autoPlay} onReplay={() => setPlayId((id) => id + 1)} />;
}

function TerminalRun({
  commands,
  autoPlay,
  onReplay,
}: {
  commands: Command[];
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const schedule = useMemo(() => buildSchedule(commands), [commands]);
  const [stepIndex, setStepIndex] = useState(autoPlay ? -1 : schedule.length - 1);
  const [finished, setFinished] = useState(!autoPlay);
  const scrollRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (!autoPlay) return;
    let cancelled = false;

    if (shouldReduceMotion) {
      const t = setTimeout(() => {
        if (cancelled) return;
        setStepIndex(schedule.length - 1);
        setFinished(true);
      }, 0);
      return () => {
        cancelled = true;
        clearTimeout(t);
      };
    }

    const timeouts = schedule.map((s, i) =>
      setTimeout(() => {
        if (!cancelled) setStepIndex(i);
      }, s.delay)
    );
    const finishDelay = (schedule[schedule.length - 1]?.delay ?? 0) + 200;
    timeouts.push(
      setTimeout(() => {
        if (!cancelled) setFinished(true);
      }, finishDelay)
    );

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
  }, [schedule, autoPlay, shouldReduceMotion]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [stepIndex]);

  const snapshot = stepIndex >= 0 ? schedule[stepIndex]?.snapshot ?? null : null;

  return (
    <div className="w-full max-w-lg overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_25px_60px_-25px_rgba(0,0,0,0.15)] dark:border-white/10 dark:bg-neutral-950 dark:shadow-[0_25px_60px_-25px_rgba(0,0,0,0.6)]">
      <div className="flex items-center gap-2 border-b border-slate-200 bg-slate-50 px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.02]">
        <span className="flex h-5 w-5 items-center justify-center rounded bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400">
          <TerminalIcon />
        </span>
        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">Terminal</span>
        {finished && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Replay commands"
            className="ml-auto inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-200 dark:focus-visible:outline-emerald-500"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div ref={scrollRef} className="max-h-64 overflow-y-auto px-4 py-3 font-mono text-[13px] leading-relaxed scrollbar-hide">
        {commands.map((c, ci) => {
          if (!snapshot || ci > snapshot.cmdIndex) return null;
          const isCurrent = ci === snapshot.cmdIndex;
          const typedLen = isCurrent ? snapshot.typedLen : c.cmd.length;
          const showingOutput = !isCurrent || snapshot.phase === "output";
          const outputCount = isCurrent ? snapshot.outputRevealed : c.output.length;
          const stillTyping = isCurrent && snapshot.phase === "typing";
          return (
            <div key={ci} className="mb-2 last:mb-0">
              <p className="text-slate-800 dark:text-slate-200">
                <span className="text-emerald-600 dark:text-emerald-500">$</span> {c.cmd.slice(0, typedLen)}
                {stillTyping && <Cursor shouldReduceMotion={shouldReduceMotion} />}
              </p>
              {showingOutput &&
                c.output.slice(0, outputCount).map((line, li) => (
                  <p key={li} className={`pl-3 ${line.tone === "success" ? "text-emerald-600 dark:text-emerald-400" : "text-slate-500 dark:text-slate-400"}`}>
                    {line.text}
                  </p>
                ))}
            </div>
          );
        })}
        {finished && (
          <p className="text-slate-800 dark:text-slate-200">
            <span className="text-emerald-600 dark:text-emerald-500">$</span> <Cursor shouldReduceMotion={shouldReduceMotion} />
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
  type PointerEvent as ReactPointerEvent,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

const BAR_COUNT = 48;
const SPEEDS = [1, 1.5, 2, 0.5];

function PlayIcon() {
  return (
    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden>
