    <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor" aria-hidden>
      <path d="M12 2.5c.4 3.6 1.4 5.9 3 7.5s3.9 2.6 7.5 3c-3.6.4-5.9 1.4-7.5 3s-2.6 3.9-3 7.5c-.4-3.6-1.4-5.9-3-7.5S5.1 13.4 1.5 13c3.6-.4 5.9-1.4 7.5-3s2.6-3.9 3-7.5z" />
    </svg>
  );
}

function VolumeIcon({ muted }: { muted: boolean }) {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M4 9v6h4l5 4V5L8 9H4Z" fill="currentColor" stroke="none" />
      {muted ? (
        <path d="M16 9l5 6M21 9l-5 6" />
      ) : (
        <>
          <path d="M16.3 8.5a5 5 0 0 1 0 7" />
          <path d="M18.7 6a8.5 8.5 0 0 1 0 12" />
        </>
      )}
    </svg>
  );
}

function UploadIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 15V4" />
      <path d="m7.5 8.5 4.5-4.5 4.5 4.5" />
      <path d="M4 15v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3" />
    </svg>
