function formatTime(s: number) {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, "0")}`;
}

function VolumeControl({ volume, muted, toggleMute, onVolumeChange }: { volume: number; muted: boolean; toggleMute: () => void; onVolumeChange: (v: number) => void }) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);
  const effective = muted ? 0 : volume;

  const setFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    onVolumeChange(Math.round(frac * 100) / 100);
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    setFromClientX(e.clientX);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    setFromClientX(e.clientX);
  };
  const onPointerUp = () => setDragging(false);

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      onVolumeChange(Math.max(0, Math.round((effective - 0.1) * 100) / 100));
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      onVolumeChange(Math.min(1, Math.round((effective + 0.1) * 100) / 100));
    }
  };

  return (
    <div className="ml-auto flex items-center gap-1.5">
      <button
        type="button"
        onClick={toggleMute}
        aria-label={muted || volume === 0 ? "Unmute" : "Mute"}
        aria-pressed={muted}
        className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-slate-300"
      >
        <VolumeIcon muted={muted || volume === 0} />
      </button>
      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-label="Volume"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(effective * 100)}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onKeyDown={onKeyDown}
        className="group relative flex h-4 w-12 cursor-pointer items-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
      >
        <div className="relative h-1 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-white/10">
          <div className="h-full rounded-full bg-emerald-500" style={{ width: `${effective * 100}%` }} />
        </div>
        <div
          aria-hidden
          className={`absolute top-1/2 h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-emerald-600 ring-2 ring-white transition-opacity duration-150 dark:ring-neutral-950 ${
            dragging ? "opacity-100" : "opacity-0 group-hover:opacity-100"
          }`}
          style={{ left: `${effective * 100}%` }}
        />
      </div>
    </div>
  );
}

function EmptyState({ onUpload }: { onUpload: () => void }) {
  return (
    <button
      type="button"
      onClick={onUpload}
      className="flex w-full flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 py-7 text-slate-400 transition-colors hover:border-emerald-400 hover:text-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/15 dark:text-slate-500 dark:hover:border-emerald-500/50 dark:hover:text-emerald-400"
    >
      <UploadIcon />
      <span className="text-xs font-medium">Upload an audio file</span>
    </button>
  );
}

// title/src: pass your own audio file as the initial track. durationSeconds is
// only the pre-load estimate shown before the file's real metadata arrives.
// The scrubber also lets the visitor swap in their own file or clear it
// entirely (the upload/trash icons next to the volume control); src only
// seeds the initial state, it isn't a controlled prop after that.
export function AudioScrubber({ title, src, durationSeconds = 0 }: { title: string; src: string; durationSeconds?: number }) {
  const [currentSrc, setCurrentSrc] = useState<string | null>(src);
  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(durationSeconds);
  const [speed, setSpeed] = useState(1);
  const [dragging, setDragging] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [muted, setMuted] = useState(false);
  const audioRef = useRef<HTMLAudioElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const fillRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Only the object URL created from a user-uploaded file needs revoking,
  // never the initial `src` prop, so it's tracked separately from currentSrc.
  const uploadedUrlRef = useRef<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const applyProgress = (time: number, dur: number) => {
    const pct = `${dur > 0 ? Math.min(1, Math.max(0, time / dur)) * 100 : 0}%`;
    if (fillRef.current) fillRef.current.style.width = pct;
    if (thumbRef.current) thumbRef.current.style.left = pct;
    if (trackRef.current) {
      trackRef.current.setAttribute("aria-valuenow", String(Math.round(time)));
      trackRef.current.setAttribute("aria-valuetext", `${formatTime(time)} of ${formatTime(dur)}`);
    }
  };

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) audio.playbackRate = speed;
  }, [speed]);

  useEffect(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.volume = volume;
      audio.muted = muted;
    }
  }, [volume, muted]);

  useEffect(() => {
    if (!playing || !currentSrc) return;
    let raf: number;
    let lastWhole = Math.floor(audioRef.current?.currentTime ?? 0);
    const tick = () => {
      const audio = audioRef.current;
      if (!audio) return;
      const dur = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : duration;
      applyProgress(audio.currentTime, dur);
      const whole = Math.floor(audio.currentTime);
      if (whole !== lastWhole) {
        lastWhole = whole;
        setCurrentTime(audio.currentTime);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [playing, duration, currentSrc]);

  const handleLoadedMetadata = () => {
    const audio = audioRef.current;
    if (audio && Number.isFinite(audio.duration) && audio.duration > 0) setDuration(audio.duration);
  };

  const handleEnded = () => {
    const audio = audioRef.current;
    const time = audio?.duration ?? duration;
    setPlaying(false);
    setCurrentTime(time);
    applyProgress(time, duration);
  };

  const handleSeek = (time: number) => {
    const clamped = Math.min(duration, Math.max(0, time));
    const audio = audioRef.current;
    if (audio) audio.currentTime = clamped;
    applyProgress(clamped, duration);
    setCurrentTime(clamped);
  };

  const seekFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    handleSeek(frac * duration);
  };

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
      setPlaying(false);
      setCurrentTime(audio.currentTime);
      return;
    }
    if (audio.currentTime >= duration - 0.05) audio.currentTime = 0;
    audio.play().catch(() => {});
    setPlaying(true);
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    seekFromClientX(e.clientX);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    seekFromClientX(e.clientX);
  };
  const onPointerUp = () => setDragging(false);

  const toggleMute = () => setMuted((m) => !m);
  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (v > 0 && muted) setMuted(false);
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const at = audioRef.current?.currentTime ?? currentTime;
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      handleSeek(at - 5);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      handleSeek(at + 5);
    } else if (e.key === "Home") {
      e.preventDefault();
      handleSeek(0);
    } else if (e.key === "End") {
      e.preventDefault();
      handleSeek(duration);
    } else if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      togglePlay();
    }
  };

  const resetPlayback = () => {
    setPlaying(false);
    setCurrentTime(0);
    setDuration(durationSeconds);
  };

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    // Local-only preview: this creates a blob URL that only exists in this
    // browser tab. A real app would typically upload `file` to its backend
    // here and use the returned hosted URL instead (or alongside this one),
    // and would still need to revoke the local object URL to avoid leaking it.
    const url = URL.createObjectURL(file);
    uploadedUrlRef.current = url;
    resetPlayback();
    setCurrentSrc(url);
  };

  const deleteAudio = () => {
    audioRef.current?.pause();
    if (uploadedUrlRef.current) {
      URL.revokeObjectURL(uploadedUrlRef.current);
      uploadedUrlRef.current = null;
    }
    resetPlayback();
    setCurrentSrc(null);
  };

  useEffect(() => {
    return () => {
      if (uploadedUrlRef.current) URL.revokeObjectURL(uploadedUrlRef.current);
    };
  }, []);

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <input ref={fileInputRef} type="file" accept="audio/*" onChange={handleFileChange} className="hidden" />
      {currentSrc && (
        <audio ref={audioRef} src={currentSrc} preload="metadata" onLoadedMetadata={handleLoadedMetadata} onEnded={handleEnded} className="hidden" />
      )}
      <div className="mb-3 flex items-center gap-2">
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          <SpeakerIcon />
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{title}</span>
        {currentSrc ? (
          <>
            <VolumeControl volume={volume} muted={muted} toggleMute={toggleMute} onVolumeChange={handleVolumeChange} />
            <button
              type="button"
              onClick={() => setSpeed((s) => SPEEDS[(SPEEDS.indexOf(s) + 1) % SPEEDS.length])}
              className="rounded-full border border-slate-200 px-2 py-0.5 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
            >
              {speed}x
            </button>
            <button
              type="button"
              onClick={openFilePicker}
              aria-label="Change audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-slate-300"
            >
              <UploadIcon />
            </button>
            <button
              type="button"
              onClick={deleteAudio}
              aria-label="Delete audio file"
              className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-500 dark:hover:text-rose-400"
            >
              <TrashIcon />
            </button>
          </>
        ) : (
          <button
            type="button"
            onClick={openFilePicker}
            className="ml-auto rounded-full border border-slate-200 px-2.5 py-1 text-[11px] font-medium text-slate-500 transition-colors hover:border-slate-300 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:text-slate-400 dark:hover:border-white/20 dark:hover:text-slate-200"
          >
            Upload
          </button>
        )}
      </div>

      {!currentSrc ? (
        <EmptyState onUpload={openFilePicker} />
      ) : (
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={togglePlay}
            aria-label={playing ? "Pause" : "Play"}
            className="relative inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white shadow-[0_4px_14px_-4px_rgba(5,150,105,0.6)] transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
          >
            <AnimatePresence mode="wait" initial={false}>
              <motion.span
                key={playing ? "pause" : "play"}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                transition={{ duration: 0.15 }}
                className="flex items-center justify-center"
              >
                {playing ? <PauseIcon /> : <PlayIcon />}
              </motion.span>
            </AnimatePresence>
          </button>

          <div className="min-w-0 flex-1">
            <div
              ref={trackRef}
              role="slider"
              tabIndex={0}
              aria-label="Seek"
              aria-valuemin={0}
              aria-valuemax={Math.round(duration)}
              aria-valuenow={Math.round(currentTime)}
              aria-valuetext={`${formatTime(currentTime)} of ${formatTime(duration)}`}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}
              onKeyDown={onKeyDown}
              className="group relative flex h-5 w-full cursor-pointer items-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
            >
              <div
                className={`relative w-full overflow-hidden rounded-full bg-slate-200 transition-[height] duration-150 dark:bg-white/10 ${
                  dragging ? "h-1.5" : "h-1 group-hover:h-1.5"
                }`}
              >
                <div ref={fillRef} className="absolute inset-y-0 left-0 rounded-full bg-emerald-500" style={{ width: `${(currentTime / duration) * 100}%` }} />
              </div>
              <div
                ref={thumbRef}
                aria-hidden
                className={`absolute top-1/2 h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-emerald-600 shadow-[0_1px_4px_rgba(0,0,0,0.35)] ring-2 ring-white transition-opacity duration-150 dark:ring-neutral-950 ${
                  dragging ? "opacity-100" : "opacity-0 group-hover:opacity-100"
                }`}
                style={{ left: `${(currentTime / duration) * 100}%` }}
              />
            </div>
            <div className="mt-1 flex items-center justify-between text-[11px] tabular-nums text-slate-400 dark:text-slate-500">
              <span>{formatTime(currentTime)}</span>
              <span>{formatTime(duration)}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

interface PersonaDef {
  id: string;
  name: string;
  role: string;
  description: string;
  traits: string[];
  orb: string;
  glow: string;
}

function CheckDotIcon() {
  return <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />;
}

function AvatarOrb({ persona, size, thinking, shouldReduceMotion }: { persona: PersonaDef; size: number; thinking: boolean; shouldReduceMotion: boolean | null }) {
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <motion.span
        aria-hidden
        className="absolute rounded-full blur-lg"
        style={{ inset: -6, background: persona.glow }}
        animate={shouldReduceMotion ? { opacity: 0.5 } : { opacity: thinking ? [0.4, 0.75, 0.4] : [0.35, 0.5, 0.35] }}
        transition={{ duration: thinking ? 1 : 3, repeat: Infinity, ease: "easeInOut" }}
      />

      {!shouldReduceMotion && (
        <motion.svg
          aria-hidden
          viewBox="0 0 100 100"
          className="absolute"
          style={{ inset: -9 }}
          animate={{ rotate: 360 }}
          transition={{ duration: thinking ? 2.2 : 9, repeat: Infinity, ease: "linear" }}
        >
          <circle cx="50" cy="50" r="47" fill="none" stroke={persona.glow} strokeWidth="1.5" strokeDasharray="1 7" strokeLinecap="round" opacity="0.7" />
        </motion.svg>
      )}

      {!shouldReduceMotion && (
        <motion.div
          aria-hidden
          className="absolute inset-[-5px]"
          animate={{ rotate: 360 }}
          transition={{ duration: thinking ? 1.6 : 4.5, repeat: Infinity, ease: "linear" }}
        >
          <span className="absolute left-1/2 top-0 h-1 w-1 -translate-x-1/2 rounded-full bg-white shadow-[0_0_6px_1.5px_rgba(255,255,255,0.9)]" />
        </motion.div>
      )}

      <span className="relative block h-full w-full overflow-hidden rounded-full ring-1 ring-white/25" style={{ background: persona.orb }}>
        <motion.span
          aria-hidden
          className="absolute inset-[-30%]"
          style={{ background: "conic-gradient(from 0deg, transparent 0%, rgba(255,255,255,0.4) 8%, transparent 20%)" }}
          animate={shouldReduceMotion ? undefined : { rotate: 360 }}
          transition={{ duration: thinking ? 1.4 : 6, repeat: Infinity, ease: "linear" }}
        />
        <span aria-hidden className="pointer-events-none absolute left-[20%] top-[14%] h-[32%] w-[32%] rounded-full bg-white/50 blur-[2px]" />
      </span>
    </div>
  );
}

function StatusBadge({ thinking }: { thinking: boolean }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[11px] font-medium ${
        thinking ? "bg-amber-500/10 text-amber-700 dark:text-amber-400" : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400"
      }`}
    >
      {thinking ? (
        <motion.span
          aria-hidden
          className="h-2 w-2 rounded-full border-[1.5px] border-amber-400/30 border-t-amber-600 dark:border-t-amber-400"
          animate={{ rotate: 360 }}
          transition={{ duration: 0.7, repeat: Infinity, ease: "linear" }}
        />
      ) : (
        <CheckDotIcon />
      )}
      {thinking ? "Thinking" : "Active"}
    </span>
  );
}

export function Persona({ personas, initialId }: { personas: PersonaDef[]; initialId?: string }) {
  const [activeId, setActiveId] = useState(initialId ?? personas[0].id);
  const [thinking, setThinking] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const active = personas.find((p) => p.id === activeId) ?? personas[0];

  useEffect(() => {
    if (!thinking) return;
    const t = setTimeout(() => setThinking(false), shouldReduceMotion ? 30 : 550);
    return () => clearTimeout(t);
  }, [thinking, shouldReduceMotion]);

  const switchPersona = (id: string) => {
    if (id === activeId) return;
    setActiveId(id);
    setThinking(true);
  };

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <AnimatePresence mode="wait">
        <motion.div
          key={activeId}
          initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
          transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
        >
          <div className="flex items-start gap-3">
            <AvatarOrb persona={active} size={44} thinking={thinking} shouldReduceMotion={shouldReduceMotion} />
            <div className="min-w-0 flex-1 pt-0.5">
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="text-sm font-semibold text-slate-900 dark:text-white">{active.name}</h3>
                <StatusBadge thinking={thinking} />
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400">{active.role}</p>
            </div>
          </div>

          <p className="mt-3 text-sm leading-relaxed text-slate-600 dark:text-slate-300">{active.description}</p>

          <div className="mt-3 flex flex-wrap gap-1.5">
            {active.traits.map((t, i) => (
              <motion.span
                key={t}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.25, delay: 0.1 + i * 0.05, ease: [0.22, 1, 0.36, 1] }}
                className="rounded-full bg-black/[0.04] px-2.5 py-1 text-[11px] font-medium text-slate-600 dark:bg-white/[0.06] dark:text-slate-300"
              >
                {t}
              </motion.span>
            ))}
          </div>
        </motion.div>
      </AnimatePresence>

      {personas.length > 1 && (
        <div className="mt-4 flex items-center gap-2 border-t border-slate-100 pt-3 dark:border-white/5">
          <span className="text-[11px] font-medium text-slate-400 dark:text-slate-500">Switch persona</span>
          <div role="tablist" aria-label="Persona" className="ml-auto flex gap-1.5">
            {personas.map((p) => (
              <button
                key={p.id}
                type="button"
                role="tab"
                aria-selected={p.id === activeId}
                aria-label={p.name}
                title={p.name}
                onClick={() => switchPersona(p.id)}
                className={`rounded-full transition-all focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                  p.id === activeId ? "ring-2 ring-emerald-500/60 ring-offset-2 ring-offset-white dark:ring-offset-neutral-950" : "opacity-70 hover:opacity-100"
                }`}
              >
                <span className="block h-6 w-6 rounded-full" style={{ background: p.orb }} />
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

const WORD_MS = 70;
const FINALIZE_PAUSE = 350;
const CHUNK_GAP = 200;

interface ScheduleStep {
  delay: number;
  chunkIndex: number;
  wordCount: number;
  finalized: boolean;
}

function buildSchedule(chunks: string[]): ScheduleStep[] {
  const steps: ScheduleStep[] = [];
  let t = 0;
  chunks.forEach((chunk, ci) => {
    const words = chunk.split(" ");
    words.forEach((_, wi) => {
      t += WORD_MS;
      steps.push({ delay: t, chunkIndex: ci, wordCount: wi + 1, finalized: false });
    });
    t += FINALIZE_PAUSE;
    steps.push({ delay: t, chunkIndex: ci, wordCount: words.length, finalized: true });
    t += CHUNK_GAP;
  });
  return steps;
}

// The Web Speech API has no official TS lib entry, so this is the minimal
// shape this component actually reads/writes from SpeechRecognition.
interface SpeechRecognitionAlternativeLike {
  transcript: string;
}
interface SpeechRecognitionResultLike {
  readonly length: number;
  isFinal: boolean;
  [index: number]: SpeechRecognitionAlternativeLike;
}
interface SpeechRecognitionResultListLike {
  readonly length: number;
  [index: number]: SpeechRecognitionResultLike;
}
interface SpeechRecognitionEventLike extends Event {
  resultIndex: number;
  results: SpeechRecognitionResultListLike;
}
interface SpeechRecognitionErrorEventLike extends Event {
  error: string;
}
interface SpeechRecognitionLike extends EventTarget {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  onresult: ((event: SpeechRecognitionEventLike) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEventLike) => void) | null;
  onend: (() => void) | null;
}
interface SpeechRecognitionConstructor {
  new (): SpeechRecognitionLike;
}

function getSpeechRecognitionCtor(): SpeechRecognitionConstructor | null {
  if (typeof window === "undefined") return null;
  const w = window as unknown as {
    SpeechRecognition?: SpeechRecognitionConstructor;
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
  };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

function MicIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <rect x="9" y="2" width="6" height="12" rx="3" />
      <path d="M5 10a7 7 0 0 0 14 0" />
      <path d="M12 19v3" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

function StopIcon() {
  return (
    <svg viewBox="0 0 24 24" width="11" height="11" fill="currentColor" aria-hidden>
      <rect x="6" y="6" width="12" height="12" rx="2" />
    </svg>
  );
}

function ReplayIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 12a9 9 0 1 0 2.6-6.3" />
      <path d="M3 4v5h5" />
    </svg>
  );
}

function ChevronDownIcon() {
  return (
    <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

const WAVEFORM_BARS = [
  { peak: 10, duration: 0.8, delay: 0 },
  { peak: 15, duration: 0.7, delay: 0.08 },
  { peak: 18, duration: 0.85, delay: 0.16 },
  { peak: 13, duration: 0.75, delay: 0.24 },
];

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

type Phase = "demo" | "listening" | "done";

interface Language {
  id: string;
  label: string;
}

export function Transcription({
  chunks,
  languages,
  autoPlay = true,
}: {
  chunks: string[];
  languages: Language[];
  autoPlay?: boolean;
}) {
  const schedule = useMemo(() => buildSchedule(chunks), [chunks]);
  const [phase, setPhase] = useState<Phase>(autoPlay ? "demo" : "done");
  const [source, setSource] = useState<"script" | "live">("script");
  const [stepIndex, setStepIndex] = useState(autoPlay ? -1 : schedule.length - 1);
  const [finalText, setFinalText] = useState("");
  const [interimText, setInterimText] = useState("");
  const [elapsedMs, setElapsedMs] = useState(0);
  const [micError, setMicError] = useState<string | null>(null);
  const [languageId, setLanguageId] = useState(languages[0]?.id ?? "");
  const [languageOpen, setLanguageOpen] = useState(false);

  const startRef = useRef(0);
  const timeoutsRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const micErrorTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const languageRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const language = languages.find((l) => l.id === languageId) ?? languages[0];

  const clearTimeouts = () => {
    timeoutsRef.current.forEach(clearTimeout);
    timeoutsRef.current = [];
  };

  const playDemo = () => {
    clearTimeouts();
    setStepIndex(-1);
    startRef.current = performance.now();
    setElapsedMs(0);
    setSource("script");
    setPhase("demo");

    if (shouldReduceMotion) {
      timeoutsRef.current.push(
        setTimeout(() => {
          setStepIndex(schedule.length - 1);
          setPhase("done");
        }, 0)
      );
      return;
    }

    schedule.forEach((s, i) => {
      timeoutsRef.current.push(setTimeout(() => setStepIndex(i), s.delay));
    });
    const finishDelay = (schedule[schedule.length - 1]?.delay ?? 0) + 250;
    timeoutsRef.current.push(setTimeout(() => setPhase("done"), finishDelay));
  };

  useEffect(() => {
    if (!autoPlay) return;
    playDemo();
    return () => clearTimeouts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (phase === "done") return;
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [phase]);

  useEffect(() => {
    return () => {
      clearTimeouts();
      if (micErrorTimeoutRef.current) clearTimeout(micErrorTimeoutRef.current);
      const recognition = recognitionRef.current;
      if (recognition) {
        recognition.onresult = null;
        recognition.onerror = null;
        recognition.onend = null;
        recognition.stop();
        recognitionRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!languageOpen) return;
    const onClick = (e: MouseEvent) => {
      if (languageRef.current && !languageRef.current.contains(e.target as Node)) setLanguageOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setLanguageOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onClick);
      document.removeEventListener("keydown", onKey);
    };
  }, [languageOpen]);

  const showMicError = (message: string) => {
    setMicError(message);
    if (micErrorTimeoutRef.current) clearTimeout(micErrorTimeoutRef.current);
    micErrorTimeoutRef.current = setTimeout(() => setMicError(null), 3200);
  };

  const startRecording = () => {
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) {
      showMicError("This browser doesn't support live transcription. Try Chrome, Edge, or Safari.");
      return;
    }

    setMicError(null);
    setLanguageOpen(false);
    clearTimeouts();

    const recognition = new Ctor();
    recognition.lang = language?.id ?? "en-US";
    recognition.continuous = true;
    recognition.interimResults = true;

    // Accumulated outside React state so results aren't lost to stale
    // closures across the many onresult events a single session fires.
    let finalSoFar = "";

    recognition.onresult = (event) => {
      let interim = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        const transcript = result[0]?.transcript ?? "";
        if (result.isFinal) {
          finalSoFar += `${transcript} `;
        } else {
          interim += transcript;
        }
      }
      setFinalText(finalSoFar);
      setInterimText(interim);
    };

    recognition.onerror = (event) => {
      if (event.error === "not-allowed" || event.error === "service-not-allowed") {
        showMicError("Microphone access was denied.");
      } else if (event.error === "audio-capture") {
        showMicError("Couldn't access the microphone.");
      } else if (event.error !== "no-speech" && event.error !== "aborted") {
        showMicError("Transcription stopped unexpectedly.");
      }
    };

    recognition.onend = () => {
      recognitionRef.current = null;
      setSource("live");
      setPhase("done");
    };

    recognitionRef.current = recognition;
    setFinalText("");
    setInterimText("");
    startRef.current = performance.now();
    setElapsedMs(0);
    setPhase("listening");

    try {
      recognition.start();
    } catch {
      recognitionRef.current = null;
      showMicError("Couldn't start the microphone.");
      setPhase("done");
    }
  };

  const stopRecording = () => {
    recognitionRef.current?.stop();
  };

  const toggleRecording = () => {
    if (phase === "listening") {
      stopRecording();
      return;
    }
    startRecording();
  };

  const listening = phase === "listening";
  const finished = phase === "done";
  const snapshot = stepIndex >= 0 ? schedule[stepIndex] : null;
  const statusLabel = finished ? "Transcribed" : "Listening";
  const liveTranscript = `${finalText}${interimText}`.trim();

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-4 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="mb-3 flex items-center justify-between gap-2">
        <button
          type="button"
          onClick={toggleRecording}
          aria-pressed={listening}
          aria-label={listening ? "Stop recording" : "Record audio to transcribe"}
          className={`relative inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
            listening
              ? "border-amber-700/30 bg-amber-700 text-white"
              : "border-slate-900/10 bg-black/[0.02] text-slate-600 hover:border-slate-900/20 hover:bg-black/5 hover:text-slate-800 dark:border-white/10 dark:bg-white/5 dark:text-slate-300 dark:hover:border-white/20 dark:hover:bg-white/10 dark:hover:text-white"
          }`}
        >
          {listening && (
            <motion.span
              aria-hidden
              className="absolute inset-[-3px] rounded-full border border-amber-400/60"
              animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
              transition={{ duration: 1.1, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          {listening ? <StopIcon /> : <MicIcon />}
          {listening ? "Stop" : "Record"}
        </button>

        <div ref={languageRef} className="relative">
          <button
            type="button"
            onClick={() => setLanguageOpen((v) => !v)}
            disabled={listening}
            aria-haspopup="listbox"
            aria-expanded={languageOpen}
            className="inline-flex items-center gap-1.5 rounded-full border border-slate-900/10 bg-black/[0.02] px-2.5 py-1 text-xs font-medium text-slate-600 transition-colors hover:border-slate-900/20 hover:bg-black/5 hover:text-slate-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:pointer-events-none disabled:opacity-50 dark:border-white/10 dark:bg-white/5 dark:text-slate-300 dark:hover:border-white/20 dark:hover:bg-white/10 dark:hover:text-white"
          >
            {language?.label}
            <motion.span animate={{ rotate: languageOpen ? 180 : 0 }} transition={{ duration: 0.15 }} className="text-slate-400">
              <ChevronDownIcon />
            </motion.span>
          </button>
          <AnimatePresence>
            {languageOpen && (
              <motion.div
                role="listbox"
                aria-label="Transcription language"
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.95, y: -4 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: -4 }}
                transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
                style={{ transformOrigin: "top right" }}
                className="scrollbar-thin absolute right-0 top-full z-20 mt-2 max-h-32 w-40 overflow-y-auto rounded-xl border border-slate-200/70 bg-white/95 p-1 shadow-lg backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/90"
              >
                {languages.map((l) => (
                  <button
                    key={l.id}
                    type="button"
                    role="option"
                    aria-selected={l.id === languageId}
                    onClick={() => {
                      setLanguageId(l.id);
                      setLanguageOpen(false);
                    }}
                    className="flex w-full items-center justify-between gap-2 rounded-lg px-2.5 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-50 dark:text-slate-200 dark:hover:bg-slate-800/60"
                  >
                    {l.label}
                    {l.id === languageId && (
                      <span className="text-emerald-500 dark:text-emerald-400">
                        <CheckIcon />
                      </span>
                    )}
                  </button>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      <AnimatePresence>
        {micError && (
          <motion.p
            role="alert"
            initial={{ opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -4 }}
            transition={{ duration: 0.15 }}
            className="mb-2 text-xs font-medium text-rose-600 dark:text-rose-400"
          >
            {micError}
          </motion.p>
        )}
      </AnimatePresence>

      <div className="mb-3 flex items-center gap-2">
        <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-500 dark:text-emerald-400">
          {!finished && !shouldReduceMotion && (
            <motion.span
              aria-hidden
              className="absolute inset-0 rounded-full border border-emerald-400/40"
              animate={{ scale: [1, 1.5], opacity: [0.6, 0] }}
              transition={{ duration: 1.4, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          {finished ? <CheckIcon /> : <MicIcon />}
        </span>
        <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{statusLabel}</span>
        {listening && (
          <span className="flex h-3 items-end gap-0.5">
            {WAVEFORM_BARS.map((bar, i) => (
              <motion.span
                key={i}
                className="w-0.5 rounded-full bg-amber-500 dark:bg-amber-400"
                style={{ height: 3 }}
                animate={shouldReduceMotion ? undefined : { height: [3, bar.peak, 3] }}
                transition={{ duration: bar.duration, repeat: Infinity, ease: "easeInOut", delay: bar.delay }}
              />
            ))}
          </span>
        )}
        <span className="ml-auto shrink-0 text-xs tabular-nums text-slate-400 dark:text-slate-500">{formatElapsed(elapsedMs)}</span>
        {finished && source === "script" && autoPlay && (
          <button
            type="button"
            onClick={playDemo}
            aria-label="Replay transcription"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <p className="min-h-[1.25rem] text-sm leading-relaxed">
        {phase === "listening" ? (
          <>
            <span className="text-slate-800 dark:text-slate-100">{finalText}</span>
            <span className="italic text-slate-500 dark:text-slate-400">{interimText}</span>
            {!finalText && !interimText && (
              <span className="italic text-slate-400 dark:text-slate-500">Listening for speech…</span>
            )}
          </>
        ) : source === "live" ? (
          liveTranscript ? (
            <span className="text-slate-800 dark:text-slate-100">{liveTranscript}</span>
          ) : (
            !micError && (
              <span className="italic text-slate-400 dark:text-slate-500">No speech detected. Press Record and try again.</span>
            )
          )
        ) : (
          chunks.map((chunk, ci) => {
            if (!snapshot || ci > snapshot.chunkIndex) return null;
            const isCurrent = ci === snapshot.chunkIndex;
            const isFinal = !isCurrent || snapshot.finalized;
            const words = chunk.split(" ");
            const visible = isCurrent ? words.slice(0, snapshot.wordCount).join(" ") : chunk;
            return (
              <motion.span
                key={ci}
                animate={{ opacity: isFinal ? 1 : 0.55 }}
                transition={{ duration: 0.25 }}
                className={`${isFinal ? "text-slate-800 dark:text-slate-100" : "italic text-slate-500 dark:text-slate-400"} `}
              >
                {visible + " "}
              </motion.span>
            );
          })
        )}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

interface Voice {
  id: string;
  name: string;
  accent: string;
}

const PREVIEW_MS = 1800;

function CheckIcon() {
  return (
    <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

function PlayIcon() {
  return (
    <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor" aria-hidden>
      <path d="M8 5.5v13l11-6.5-11-6.5Z" />
    </svg>
  );
}

function StopIcon() {
  return (
    <svg viewBox="0 0 24 24" width="10" height="10" fill="currentColor" aria-hidden>
      <rect x="5" y="5" width="14" height="14" rx="2" />
    </svg>
  );
}

function PreviewButton({
  playing,
  onClick,
  label,
  shouldReduceMotion,
}: {
  playing: boolean;
  onClick: () => void;
  label: string;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={playing ? `Stop preview of ${label}` : `Preview ${label}`}
      title={playing ? "Stop preview" : "Preview voice"}
      className={`relative inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
        playing
          ? "bg-emerald-600 text-white"
          : "bg-black/5 text-slate-500 hover:bg-black/10 hover:text-slate-700 dark:bg-white/10 dark:text-slate-400 dark:hover:bg-white/15 dark:hover:text-slate-200"
      }`}
    >
      {playing && (
        <motion.span
          aria-hidden
          className="absolute inset-[-3px] rounded-full border border-emerald-400/50"
          animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
          transition={{ duration: 1, repeat: Infinity, ease: "easeOut" }}
        />
      )}
      {playing ? <StopIcon /> : <PlayIcon />}
    </button>
  );
}

export function VoiceSelector({
  voices,
  defaultSelectedId,
  onSelect,
}: {
  voices: Voice[];
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
}) {
  const [selectedId, setSelectedId] = useState(defaultSelectedId ?? voices[0].id);
  const [previewingId, setPreviewingId] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const togglePreview = (id: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (previewingId === id) {
      setPreviewingId(null);
      return;
    }
    setPreviewingId(id);
    timeoutRef.current = setTimeout(() => setPreviewingId(null), PREVIEW_MS);
  };

  const select = (id: string) => {
    setSelectedId(id);
    onSelect?.(id);
  };

  const selected = voices.find((v) => v.id === selectedId) ?? voices[0];

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-2 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="flex items-center justify-between px-2 pb-1.5 pt-1">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Voice</p>
        <p className="text-xs font-medium text-emerald-600 dark:text-emerald-400">{selected.name}</p>
      </div>
      <ul role="radiogroup" aria-label="Select a voice" className="flex flex-col gap-0.5">
        {voices.map((v) => {
          const isSelected = v.id === selectedId;
          const isPlaying = previewingId === v.id;
          return (
            <li key={v.id}>
              <div
                className={`flex items-center gap-2 rounded-lg px-2 py-1.5 transition-colors ${
                  isSelected ? "bg-emerald-500/8 dark:bg-emerald-400/10" : "hover:bg-black/[0.03] dark:hover:bg-white/5"
                }`}
              >
                <button
                  type="button"
                  role="radio"
                  aria-checked={isSelected}
                  onClick={() => select(v.id)}
                  className="flex flex-1 items-center gap-2.5 rounded-md py-0.5 text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                >
                  <span
                    className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                      isSelected ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-300 dark:border-slate-600"
                    }`}
                  >
                    {isSelected && <CheckIcon />}
                  </span>
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-slate-800 dark:text-slate-100">{v.name}</span>
                    <span className="block text-xs text-slate-400 dark:text-slate-500">{v.accent}</span>
                  </span>
                </button>
                <PreviewButton playing={isPlaying} onClick={() => togglePreview(v.id)} label={v.name} shouldReduceMotion={shouldReduceMotion} />
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";

type Status = "uploading" | "done" | "error";

interface Attachment {
  id: string;
  name: string;
  size: number;
  status: Status;
  progress: number;
  speed: number;
  failAt?: number;
}

let nextId = 1;

const RADIUS = 9;
const CIRC = 2 * Math.PI * RADIUS;

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(kb < 10 ? 1 : 0)} KB`;
  const mb = kb / 1024;
  return `${mb.toFixed(mb < 10 ? 1 : 0)} MB`;
}

function isImage(name: string) {
  return /\.(png|jpe?g|gif|webp|svg)$/i.test(name);
}

function ImageIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <rect x="3" y="3" width="18" height="18" rx="2" />
      <circle cx="9" cy="9" r="2" />
      <path d="m21 15-5-5L5 21" />
    </svg>
  );
}

function DocumentIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z" />
      <path d="M14 2v6h6" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

function XIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  );
}

function AlertIcon() {
  return (
    <svg viewBox="0 0 24 24" width="9" height="9" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 8v4" />
      <path d="M12 16h.01" />
    </svg>
  );
}

function RetryIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 12a9 9 0 1 0 2.6-6.3" />
      <path d="M3 4v5h5" />
    </svg>
  );
}

function PlusIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 5v14M5 12h14" />
    </svg>
  );
}

function FileTone({ name }: { name: string }) {
  const image = isImage(name);
  return (
    <span
      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${
        image ? "bg-emerald-500/12 text-emerald-600 dark:text-emerald-400" : "bg-amber-500/12 text-amber-600 dark:text-amber-400"
      }`}
    >
      {image ? <ImageIcon /> : <DocumentIcon />}
    </span>
  );
}

function ProgressRing({ progress, status }: { progress: number; status: Status }) {
  const offset = CIRC * (1 - progress / 100);
  const color = status === "error" ? "#e11d48" : "#059669";
  return (
    <svg viewBox="0 0 24 24" width="32" height="32" className="absolute inset-0 -rotate-90" aria-hidden>
      <circle cx="12" cy="12" r={RADIUS} fill="none" stroke="currentColor" strokeWidth="2" className="text-black/5 dark:text-white/10" />
      <motion.circle
        cx="12"
        cy="12"
        r={RADIUS}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={CIRC}
        animate={{ strokeDashoffset: offset }}
        transition={{ duration: 0.15, ease: "linear" }}
      />
    </svg>
  );
}

export function Attachments({ initialFiles = [] }: { initialFiles?: { name: string; size: number }[] }) {
  const [attachments, setAttachments] = useState<Attachment[]>(() =>
    initialFiles.map((f) => ({ id: `i${nextId++}`, name: f.name, size: f.size, status: "uploading", progress: 0, speed: 3.5 }))
  );
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const id = setInterval(() => {
      setAttachments((prev) =>
        prev.map((a) => {
          if (a.status !== "uploading") return a;
          const next = a.progress + a.speed;
          if (a.failAt !== undefined && next >= a.failAt) {
            return { ...a, progress: a.failAt, status: "error" };
          }
          if (next >= 100) {
            return { ...a, progress: 100, status: "done" };
          }
          return { ...a, progress: next };
        })
      );
    }, 80);
    return () => clearInterval(id);
  }, []);

  const remove = (id: string) => setAttachments((prev) => prev.filter((a) => a.id !== id));

  const retry = (id: string) =>
    setAttachments((prev) => prev.map((a) => (a.id === id ? { ...a, status: "uploading", progress: 0, failAt: undefined } : a)));

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const added: Attachment[] = Array.from(files).map((f) => ({
      id: `f${nextId++}`,
      name: f.name,
      size: f.size,
      status: "uploading",
      progress: 0,
      speed: 3.5,
    }));
    setAttachments((prev) => [...prev, ...added]);
  };

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-3 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <p className="px-1 pb-2 text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
        Attachments · {attachments.length}
      </p>
      <ul className="flex flex-col gap-1.5" role="list">
        <AnimatePresence initial={false}>
          {attachments.map((a) => (
            <motion.li
              key={a.id}
              layout
              initial={{ opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.94 }}
              transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="flex items-center gap-3 rounded-xl border border-transparent bg-black/[0.02] px-2.5 py-2 dark:bg-white/[0.03]"
            >
              <div className="relative h-8 w-8 shrink-0">
                <FileTone name={a.name} />
                {a.status === "uploading" && <ProgressRing progress={a.progress} status={a.status} />}
                {a.status === "done" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-emerald-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <CheckIcon />
                  </span>
                )}
                {a.status === "error" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-rose-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <AlertIcon />
                  </span>
                )}
              </div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-800 dark:text-slate-100">{a.name}</p>
                <p className={`text-xs ${a.status === "error" ? "text-rose-600 dark:text-rose-400" : "text-slate-400 dark:text-slate-500"}`}>
                  {a.status === "uploading" ? `${Math.round(a.progress)}% · ${formatBytes(a.size)}` : a.status === "error" ? "Upload failed" : formatBytes(a.size)}
                </p>
              </div>
              <div className="flex shrink-0 items-center gap-1">
                {a.status === "error" && (
                  <button
                    type="button"
                    onClick={() => retry(a.id)}
                    aria-label={`Retry uploading ${a.name}`}
                    className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                  >
                    <RetryIcon />
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => remove(a.id)}
                  aria-label={`Remove ${a.name}`}
                  className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <XIcon />
                </button>
              </div>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>

      <input
        ref={inputRef}
        type="file"
        multiple
        className="sr-only"
        onChange={(e) => {
          handleFiles(e.target.files);
          e.target.value = "";
        }}
      />
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        className="mt-1.5 flex w-full items-center justify-center gap-1.5 rounded-xl border border-dashed border-slate-300 py-2 text-xs font-medium text-slate-500 transition-colors hover:border-emerald-400 hover:text-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:text-slate-400 dark:hover:border-emerald-500/60 dark:hover:text-emerald-400"
      >
        <PlusIcon />
        Add file
      </button>
    </div>
  );
}
